import random
from typing import List

# This generator targets djitools::simple_checksum, which consumes arbitrary binary data.
# The fuzzer stub uses FUZZ_PARAM_STR to obtain 1..4096 bytes. We therefore generate a
# byte string within that range, covering interesting edge cases and typical patterns
# that exercise additive checksum behavior (e.g., zeros, max bytes, alternating patterns,
# increasing sequences, random data, and structured blocks).

MAX_LEN = 4096
MIN_LEN = 1  # FUZZ_PARAM_STR returns 1..4096 according to the stub comment


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _pattern_zero(n: int) -> bytes:
    return b"\x00" * n


def _pattern_ff(n: int) -> bytes:
    return b"\xFF" * n


def _pattern_alt01(n: int) -> bytes:
    # 0x00, 0x01, 0x00, 0x01, ...
    return bytes((i & 1) for i in range(n))


def _pattern_altff00(n: int) -> bytes:
    # 0xFF, 0x00 alternating
    return bytes(0xFF if (i & 1) == 0 else 0x00 for i in range(n))


def _pattern_inc(n: int) -> bytes:
    # 0x00, 0x01, ..., 0xFF, 0x00, ...
    return bytes(i & 0xFF for i in range(n))


def _pattern_dec(n: int) -> bytes:
    # 0xFF, 0xFE, ..., wrapping
    return bytes((0xFF - (i & 0xFF)) & 0xFF for i in range(n))


def _pattern_blocks(rng: random.Random, n: int) -> bytes:
    # Construct buffer from repeated small blocks with varying byte values
    # to stress accumulation and alignment-like behavior.
    blocks: List[bytes] = []
    remaining = n
    while remaining > 0:
        # Choose a block size between 1 and 64
        bsz = min(remaining, rng.randint(1, 64))
        mode = rng.randrange(5)
        if mode == 0:
            val = rng.randrange(256)
            blk = bytes([val]) * bsz
        elif mode == 1:
            start = rng.randrange(256)
            blk = bytes(((start + i) & 0xFF) for i in range(bsz))
        elif mode == 2:
            blk = bytes(rng.getrandbits(8) for _ in range(bsz))
        elif mode == 3:
            blk = bytes((0xFF if (i & 1) == 0 else 0x00) for i in range(bsz))
        else:
            blk = bytes((i & 1) for i in range(bsz))
        blocks.append(blk)
        remaining -= bsz
    return b"".join(blocks)


def _pattern_edge_sums(n: int) -> bytes:
    # Create data whose sum is around 0x0000, 0x00FF, 0xFF00, 0xFFFF modulo 16-bit
    # We do this by mixing zeros and 0xFFs and a tail byte to fine-tune.
    # Not exact for all lengths, but gives interesting totals.
    if n == 1:
        return bytes([0xFF])
    half = n // 2
    tail_len = n - half - 1
    # half of 0xFF, tail of 0x01, rest zeros
    return b"\xFF" * half + b"\x01" * tail_len + b"\x00"


def _choose_length(rng: random.Random) -> int:
    # Bias towards small, medium, and max sizes
    roll = rng.random()
    if roll < 0.20:
        # very small
        return rng.randint(MIN_LEN, min(16, MAX_LEN))
    elif roll < 0.60:
        # medium
        return rng.randint(17, min(512, MAX_LEN))
    elif roll < 0.90:
        # large
        return rng.randint(513, MAX_LEN - 1)
    else:
        return MAX_LEN


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    n = _choose_length(rng)

    # Choose a pattern family
    patterns = [
        lambda: _rand_bytes(rng, n),
        lambda: _pattern_zero(n),
        lambda: _pattern_ff(n),
        lambda: _pattern_alt01(n),
        lambda: _pattern_altff00(n),
        lambda: _pattern_inc(n),
        lambda: _pattern_dec(n),
        lambda: _pattern_blocks(rng, n),
        lambda: _pattern_edge_sums(n),
    ]

    # Weighted preference towards random and blocky structures
    weights = [3, 1, 1, 1, 1, 1, 1, 3, 1]
    choice_space = []
    for i, w in enumerate(weights):
        choice_space.extend([i] * w)
    pat_idx = rng.choice(choice_space)

    data = patterns[pat_idx]()

    # Ensure length bounds and type
    if not isinstance(data, (bytes, bytearray)):
        data = bytes(data)
    if len(data) < MIN_LEN:
        data = data + b"\x00" * (MIN_LEN - len(data))
    if len(data) > MAX_LEN:
        data = data[:MAX_LEN]

    return bytes(data)
